-- vr-halle-equipement
INSERT INTO public.procedure_fiches (category, title, summary, content_steps, is_placeholder, tags, is_active, is_required, scope_kind, sort_order)
SELECT 'procedure_deroulement', 'Équipement et déséquipement en halle', 'Amener le groupe en halle de jeu, l''équiper avant la partie et le déséquiper à la fin.', '[{"order": 1, "text": "Avant de quitter le salon : vestes, pulls, sacs et appareils électroniques sont dans les casiers. Conseiller de s''habiller léger."}, {"order": 2, "text": "Amener le groupe dans la halle de jeu pour la phase d''équipement."}, {"order": 3, "text": "Équiper chaque joueur : casque Meta Quest 3 et manettes (il n''y a plus de sac à dos). Réglages des casques : voir la fiche « Configuration casques Quest 3 »."}, {"order": 4, "text": "Vérifier que chaque joueur est bien équipé et à l''aise avant de lancer la partie."}, {"order": 5, "text": "Fin de partie : retirer casques et manettes à chaque client, puis les poser à leur place dans la halle."}, {"order": 6, "text": "Ramener le groupe au salon pour reprendre ses affaires dans les casiers, puis faire le débriefing."}, {"order": 7, "text": "Après le départ du groupe : nettoyer casques et manettes et faire un contrôle rapide (fiche « Nettoyage casques et manettes entre groupes »)."}]'::jsonb, false, ARRAY['vr', 'halle', 'equipement'], true, true, 'locations',
  COALESCE((SELECT max(sort_order) FROM public.procedure_fiches WHERE category = 'procedure_deroulement' AND deleted_at IS NULL), 0) + 10
WHERE NOT EXISTS (SELECT 1 FROM public.procedure_fiches WHERE title = 'Équipement et déséquipement en halle' AND deleted_at IS NULL);
INSERT INTO public.fiche_scope_locations (fiche_id, location_id)
SELECT f.id, r.id FROM public.procedure_fiches f JOIN public.locations r ON r.slug IN ('vr_center')
WHERE f.title = 'Équipement et déséquipement en halle' AND f.deleted_at IS NULL
ON CONFLICT DO NOTHING;

