-- dvc-vinum
INSERT INTO public.procedure_fiches (category, title, summary, content_steps, is_placeholder, tags, is_active, is_required, scope_kind, sort_order)
SELECT 'procedure_deroulement', 'Vinum : matériel et quantités de vin', 'Option Vinum : quoi prendre, quelles quantités servir et comment ranger verres et bouteilles.', '[{"order": 1, "text": "Matériel à prendre au stock : verres, bouteilles de vin, cadenas pour les bouteilles, porte-verres, tire-bouchons."}, {"order": 2, "text": "Vinum 1 ou 2 équipes : 1 vin rouge et 1 vin blanc (75 cl) par équipe."}, {"order": 3, "text": "Vinum 3 équipes : 1 vin blanc uniquement par équipe."}, {"order": 4, "text": "Équipe de 7 personnes ou plus : doubler sa quantité de vin. Exemple : 1 équipe de 10 personnes = 2 blancs et 2 rouges."}, {"order": 5, "text": "Respecter ces quantités : les abus sont retenus sur le salaire et le stock est sous vidéosurveillance."}, {"order": 6, "text": "Après le jeu : jeter les bouteilles sur le chemin du lieu final à la cave, sauf entre 21 h et 7 h ou entre 12 h et 13 h. Dans ce cas, les mettre dans le bac de recyclage du verre à la cave."}, {"order": 7, "text": "Séparer les verres sales des verres propres et les ranger aux emplacements étiquetés."}]'::jsonb, false, ARRAY['vinum', 'davinci', 'option'], true, true, 'games',
  COALESCE((SELECT max(sort_order) FROM public.procedure_fiches WHERE category = 'procedure_deroulement' AND deleted_at IS NULL), 0) + 10
WHERE NOT EXISTS (SELECT 1 FROM public.procedure_fiches WHERE title = 'Vinum : matériel et quantités de vin' AND deleted_at IS NULL);
