WHERE f.title = 'Vinum : matériel et quantités de vin' AND f.deleted_at IS NULL
ON CONFLICT DO NOTHING;

-- dvc-couvent
INSERT INTO public.procedure_fiches (category, title, summary, content_steps, is_placeholder, tags, is_active, is_required, scope_kind, sort_order)
SELECT 'formation_technique', 'Couvent : mise en route et arrêt de l’énigme', 'Allumer, contrôler et armer l''énigme de la grille au Couvent, puis l''éteindre après la partie.', '[{"order": 1, "text": "Prendre la petite télécommande blanche du beamer (il n''y en a qu''une, ne pas la perdre)."}, {"order": 2, "text": "Derrière l''harmonium, repérer la prise qui descend du plafond. Si elle est branchée, la débrancher, attendre environ 5 s, puis la rebrancher."}, {"order": 3, "text": "Allumer IMMÉDIATEMENT le beamer avec la télécommande (un allumage tardif donne une projection trop petite)."}, {"order": 4, "text": "Sur la tablette ou le téléphone GM, se connecter au Wi-Fi COUVENT-GM (QR code de connexion fourni avec le manuel), puis ouvrir 10.10.0.1 dans le navigateur. « Aucune connexion Internet » est normal."}, {"order": 5, "text": "Debug → Capteurs / Arduinos : GPIO PIR initialisé en vert, A1 à A4 « Connecté » en vert, les 16 « Capteur répond » en vert. Les « Objet détecté » rouges sont normaux. Revenir avec BACK TO CONTROL."}, {"order": 6, "text": "Test : appuyer sur ARM, passer devant le capteur vers l''escalier, vérifier que la vidéo d''intro démarre à la bonne taille, puis appuyer sur RESET."}, {"order": 7, "text": "Se placer dans l''escalier (hors zone de détection) et appuyer de nouveau sur ARM : le jeu est prêt."}, {"order": 8, "text": "Pendant la partie : READY → ARMED → INTRO PLAYING (environ 1 min) → GRID ACTIVE → FINAL PLAYING. Le GM n''intervient que si besoin (fiche « Dépannage : Couvent »)."}, {"order": 9, "text": "Après la partie : éteindre le beamer (2 pressions sur le bouton d''extinction), attendre l''extinction complète, puis débrancher la prise derrière l''harmonium."}, {"order": 10, "text": "Ne jamais toucher au câblage des Arduino."}]'::jsonb, false, ARRAY['couvent', 'davinci', 'technique'], true, true, 'games',
  COALESCE((SELECT max(sort_order) FROM public.procedure_fiches WHERE category = 'formation_technique' AND deleted_at IS NULL), 0) + 10
WHERE NOT EXISTS (SELECT 1 FROM public.procedure_fiches WHERE title = 'Couvent : mise en route et arrêt de l’énigme' AND deleted_at IS NULL);
INSERT INTO public.fiche_scope_games (fiche_id, game_id)
SELECT f.id, r.id FROM public.procedure_fiches f JOIN public.games r ON r.slug IN ('davinci')
WHERE f.title = 'Couvent : mise en route et arrêt de l’énigme' AND f.deleted_at IS NULL
ON CONFLICT DO NOTHING;

-- dvc-couvent-depannage
INSERT INTO public.procedure_fiches (category, title, summary, content_steps, is_placeholder, tags, is_active, is_required, scope_kind, sort_order)
SELECT 'depannage_bugs', 'Dépannage : Couvent (énigme de la grille)', 'Que faire quand l''énigme du Couvent ne se comporte pas normalement.', '[{"order": 1, "text": "Vidéo d''intro trop petite : laisser le beamer allumé, Restart → REBOOT RASPBERRY PI, attendre, se reconnecter à 10.10.0.1, recontrôler les capteurs puis refaire le test ARM + PIR."}, {"order": 2, "text": "Un Arduino ou un TF-Luna en rouge : éteindre le beamer (2 pressions), débrancher la prise 5 s, rebrancher, rallumer immédiatement le beamer, puis recontrôler Capteurs / Arduinos et refaire le test ARM + PIR."}, {"order": 3, "text": "Joueurs descendus mais le jeu reste sur ARMED : appuyer sur SIMULATE PIR."}, {"order": 4, "text": "Bonne position trouvée mais la validation retombe : appuyer sur SIMULATE PUZZLE."}, {"order": 5, "text": "Partie interrompue alors que l''énigme était presque résolue : RESET, réarmer si besoin, puis SKIP pour passer à la séquence finale."}, {"order": 6, "text": "Problème non prévu : ne pas toucher aux câbles, essayer RESET, puis REBOOT RASPBERRY PI, puis une extinction complète."}, {"order": 7, "text": "Panne persistante : éteindre complètement, passer à l''énigme papier et contacter le responsable technique."}]'::jsonb, false, ARRAY['couvent', 'davinci', 'depannage'], true, true, 'games',
  COALESCE((SELECT max(sort_order) FROM public.procedure_fiches WHERE category = 'depannage_bugs' AND deleted_at IS NULL), 0) + 10
WHERE NOT EXISTS (SELECT 1 FROM public.procedure_fiches WHERE title = 'Dépannage : Couvent (énigme de la grille)' AND deleted_at IS NULL);
INSERT INTO public.fiche_scope_games (fiche_id, game_id)
SELECT f.id, r.id FROM public.procedure_fiches f JOIN public.games r ON r.slug IN ('davinci')
WHERE f.title = 'Dépannage : Couvent (énigme de la grille)' AND f.deleted_at IS NULL
ON CONFLICT DO NOTHING;

-- dvc-script-fin
INSERT INTO public.procedure_fiches (category, title, summary, content_steps, is_placeholder, tags, is_active, is_required, scope_kind, sort_order)
SELECT 'procedure_deroulement', 'Script de fin Da Vinci Code', 'Ce qu''on raconte aux clients à la fin du Da Vinci Code.', '[{"order": 1, "text": "Le Chrisme (carré noir) : combinaison de lettres grecques, ancien signe chrétien. La croix est le « Chi » (prononcé ki), le P est le « Rho », avec l''alpha (le début) et l''oméga (la fin)."}, {"order": 2, "text": "Le X et le P superposés sont les initiales de « Christos ». À Sion, des gravures de la fin de l''Empire romain montrent qu''il y avait déjà d''importantes communautés chrétiennes à la fin de l''Antiquité."}, {"order": 3, "text": "L''acte de contrition (les morceaux de parchemin) : une confession écrite pour se repentir de ses péchés. Celui-ci est fictif ; il aurait pu être écrit par le cardinal Matthieu Schiner, que les joueurs ont croisé, notamment à la Sionne."}, {"order": 4, "text": "Schiner était prince-évêque de Sion à la fin du Moyen Âge et au début de la Renaissance, chef politique et militaire du Valais."}, {"order": 5, "text": "Le pouvoir à Sion était partagé entre les bourgeois (menés par la famille Supersaxo) et l''Église (menée par le cardinal), qui aurait demandé l''aide du Diable pour avoir le plein pouvoir. Par cet acte, il aurait reconnu ses fautes."}, {"order": 6, "text": "Fun facts : c''est grâce aux Supersaxo que Schiner a pu faire des études et devenir cardinal ; ce sont aussi les Supersaxo qui ont fait construire la Maison du Diable."}]'::jsonb, false, ARRAY['davinci', 'script', 'fin'], true, true, 'games',
  COALESCE((SELECT max(sort_order) FROM public.procedure_fiches WHERE category = 'procedure_deroulement' AND deleted_at IS NULL), 0) + 10
WHERE NOT EXISTS (SELECT 1 FROM public.procedure_fiches WHERE title = 'Script de fin Da Vinci Code' AND deleted_at IS NULL);
INSERT INTO public.fiche_scope_games (fiche_id, game_id)
