SELECT 'procedure_deroulement', 'Le Feu sacré : processus GM et rendez-vous', 'Ordre des tâches de l''animateur, lieux de rendez-vous et temps par étape selon le nombre d''équipes.', '[{"order": 1, "text": "1 équipe : préparer la Cave des Vidômes → préparer le Château Villa → début du jeu → ranger la Cave des Vidômes → faire la fin au Château Villa → ranger le Château Villa → ramener les médaillons à la Cave des Vidômes."}, {"order": 2, "text": "Rendez-vous (1 équipe) : Rue du Bourg 24, 3960 Sierre, devant le Château des Vidômes."}, {"order": 3, "text": "Temps par étape (1 équipe) : Cave des Vidômes 60 min, église Notre-Dame-des-Marais 10 min, Mercier 40 min, Villa + final 20 min."}, {"order": 4, "text": "2 équipes (1 animateur) : préparer la Cave → préparer la Villa → début → ranger la Villa → ranger la Cave → fin au Café → ranger la Villa → ranger la Cave. 2e rendez-vous : Rue Sainte-Catherine 4, devant le Château Villa. Une étape Joker (10 min) s''ajoute ; final au Café (10 min)."}, {"order": 5, "text": "3 équipes (2 animateurs) : animateur 1 prépare la Cave, début, range la Cave ×3, fait la fin au Café, aide à ranger la Cave ; animateur 2 prépare la Villa, début, range la Villa ×3. 3e rendez-vous : Chemin des Cyprès, parking du Château Mercier."}]'::jsonb, false, ARRAY['feu-sacre', 'sierre', 'processus'], true, true, 'games',
  COALESCE((SELECT max(sort_order) FROM public.procedure_fiches WHERE category = 'procedure_deroulement' AND deleted_at IS NULL), 0) + 10
WHERE NOT EXISTS (SELECT 1 FROM public.procedure_fiches WHERE title = 'Le Feu sacré : processus GM et rendez-vous' AND deleted_at IS NULL);
